prompt --application/shared_components/user_interface/lovs/lov_additional_target_organizations
begin
wwv_flow_imp_shared.create_list_of_values(
 p_id=>wwv_flow_imp.id(279381936649570393)
,p_lov_name=>'LOV_ADDITIONAL_TARGET_ORGANIZATIONS'
,p_lov_query=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT CASE',
'           WHEN hou.name IS NULL',
'               THEN mp.organization_code',
'           ELSE mp.organization_code || '' - '' || hou.name',
'       END AS display_value,',
'       cfg.ebs_organization_id AS return_value',
'  FROM ops.adre_inv_item_type_org cfg',
'  JOIN apps.mtl_parameters mp',
'    ON mp.organization_id = cfg.ebs_organization_id',
'  LEFT JOIN apps.hr_all_organization_units hou',
'    ON hou.organization_id = cfg.ebs_organization_id',
' WHERE cfg.item_type_id = :P10_ITEM_TYPE_ID',
'   AND cfg.organization_role = ''TARGET''',
'   AND cfg.active_flag = ''Y''',
'   AND cfg.auto_assign_flag = ''N''',
' ORDER BY cfg.display_sequence,',
'          mp.organization_code'))
,p_source_type=>'SQL'
,p_location=>'LOCAL'
,p_query_owner=>'AHL'
,p_return_column_name=>'RETURN_VALUE'
,p_display_column_name=>'DISPLAY_VALUE'
);
end;
/
