prompt --application/shared_components/user_interface/lovs/lov_adre_primary_uom_by_item_type
begin
wwv_flow_imp_shared.create_list_of_values(
 p_id=>wwv_flow_imp.id(278927562574925551)
,p_lov_name=>'LOV_ADRE_PRIMARY_UOM_BY_ITEM_TYPE'
,p_lov_query=>wwv_flow_string.join(wwv_flow_t_varchar2(
'/* 2026-09-07 - JCALZADILLA - Return active EBS UOM values approved for the selected Item Type. */',
'SELECT ebs_uom.unit_of_measure AS display_value,',
'       config.uom_code        AS return_value',
'  FROM ops.adre_inv_item_type_uom config',
'  JOIN apps.mtl_units_of_measure_vl ebs_uom',
'    ON ebs_uom.uom_code = config.uom_code',
' WHERE config.item_type_id = :P10_ITEM_TYPE_ID',
'   AND config.active_flag = ''Y''',
'   AND (',
'           ebs_uom.disable_date IS NULL',
'        OR ebs_uom.disable_date > SYSDATE',
'       )',
' ORDER BY config.display_sequence,',
'          ebs_uom.unit_of_measure'))
,p_source_type=>'SQL'
,p_location=>'LOCAL'
,p_use_local_sync_table=>false
,p_query_owner=>'AHL'
,p_return_column_name=>'RETURN_VALUE'
,p_display_column_name=>'DISPLAY_VALUE'
,p_group_sort_direction=>'ASC'
,p_default_sort_direction=>'ASC'
);
end;
