 p_id=>wwv_flow_imp.id(241587638974141706)
,p_name=>'Attributes'
,p_parent_plug_id=>wwv_flow_imp.id(241587413570141704)
,p_template=>wwv_flow_imp.id(510639143595698094)
,p_display_sequence=>30
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_component_template_options=>'#DEFAULT#:t-Report--altRowsDefault:t-Report--rowHighlight'
,p_display_point=>'SUB_REGIONS'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT av.item_attr_value_id,',
'       ro.organization_role,',
'       mp.organization_code,',
'       a.attribute_name,',
'       a.attribute_data_type,',
'       CASE',
'           WHEN a.attribute_data_type = ''NUMBER''',
'               THEN TO_CHAR(av.attribute_number_value)',
'           WHEN a.attribute_data_type = ''DATE''',
'               THEN TO_CHAR(av.attribute_date_value, ''MM/DD/YYYY'')',
'           ELSE av.attribute_char_value',
'       END AS attribute_value,',
'       av.value_uom_code,',
'       ita.required_flag,',
'       av.value_status',
'  FROM ops.adre_inv_item_request_org ro',
'  JOIN apps.mtl_parameters mp',
'    ON mp.organization_id = ro.ebs_organization_id',
'  JOIN ops.adre_inv_item_attr_value av',
'    ON av.request_org_id = ro.request_org_id',
'  JOIN ops.adre_inv_item_attribute a',
'    ON a.item_attribute_id = av.item_attribute_id',
'  JOIN ops.adre_inv_item_request r',
'    ON r.item_request_id = ro.item_request_id',
'  JOIN ops.adre_inv_item_type_attr ita',
'    ON ita.item_type_id = r.item_type_id',
'   AND ita.item_attribute_id = av.item_attribute_id',
'   AND ita.organization_scope = ro.organization_role',
' WHERE ro.item_request_id = :P10_ITEM_REQUEST_ID',
' ORDER BY CASE ro.organization_role',
'              WHEN ''MASTER'' THEN 1',
'              WHEN ''TARGET'' THEN 2',
'              ELSE 3',
'          END,',
'          mp.organization_code,',
'          ita.display_sequence,',
'          a.attribute_name',
''))
,p_ajax_enabled=>'Y'
,p_ajax_items_to_submit=>'P10_ITEM_REQUEST_ID'
,p_lazy_loading=>false
,p_query_row_template=>wwv_flow_imp.id(510677293149698108)
,p_query_num_rows=>15
,p_query_options=>'DERIVED_REPORT_COLUMNS'
,p_query_num_rows_type=>'NEXT_PREVIOUS_LINKS'
,p_pagination_display_position=>'BOTTOM_RIGHT'
