,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT ro.organization_role AS role,',
'       mp.organization_code AS organization,',
'       NVL(mt.template_name, ''Pending backend resolution'') AS template,',
'       ro.assignment_status  AS status',
'  FROM ops.adre_inv_item_request_org ro',
'  JOIN apps.mtl_parameters mp',
'    ON mp.organization_id = ro.ebs_organization_id',
'  LEFT JOIN apps.mtl_item_templates mt',
'    ON mt.template_id = ro.ebs_template_id',
' WHERE ro.item_request_id = :P10_ITEM_REQUEST_ID',
' ORDER BY CASE ro.organization_role',
'              WHEN ''MASTER'' THEN 1',
'              WHEN ''TARGET'' THEN 2',
'              ELSE 3',
'          END,',
'          mp.organization_code'))
,p_ajax_enabled=>'Y'
