,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT cat.item_category_id,',
'       ro.request_org_id,',
'       cfg.category_set_id AS ebs_category_set_id,',
'       mp.organization_code,',
'       cfg.category_set_name,',
'       NVL(cat.category_value, ''Not selected'') AS category_value,',
'       NVL(cat.assignment_status, ''Not selected'') AS assignment_status',
'  FROM ops.adre_inv_item_request_org ro',
'  JOIN apps.mtl_parameters mp',
'    ON mp.organization_id = ro.ebs_organization_id',
' CROSS JOIN ops.adre_cat_sets cfg',
'  JOIN apps.mtl_category_sets_b cs',
'    ON cs.category_set_id = cfg.category_set_id',
'  LEFT JOIN ops.adre_inv_item_category cat',
'    ON cat.request_org_id = ro.request_org_id',
'   AND cat.ebs_category_set_id = cfg.category_set_id',
' WHERE ro.item_request_id = :P10_ITEM_REQUEST_ID',
'   AND ro.organization_role = ''MASTER''',
'   AND cs.control_level = 1',
' ORDER BY cfg.category_set_name'))
,p_ajax_enabled=>'Y'
,p_ajax_items_to_submit=>'P10_ITEM_REQUEST_ID'
,p_lazy_loading=>false
