,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'/* 2026-09-07 - JCALZADILLA - Return active EBS UOM values approved for the selected Item Type. */',
'SELECT ebs_uom.unit_of_measure AS display_value,',
'       config.uom_code        AS return_value',
'  FROM ops.adre_inv_item_type_uom config',
'  JOIN apps.mtl_units_of_measure_vl ebs_uom',
'    ON ebs_uom.uom_code = config.uom_code',
' WHERE config.item_type_id = :P10_ITEM_TYPE_ID',
'   AND config.active_flag = ''Y''',
'   AND (',
'           ebs_uom.disable_date IS NULL',
'        OR ebs_uom.disable_date > SYSDATE',
'       )',
' ORDER BY config.display_sequence,',
'          ebs_uom.unit_of_measure'))
