,p_prompt=>'Additional Target Organizations'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT LISTAGG(',
'           TO_CHAR(ro.ebs_organization_id),',
'           '':''',
'       ) WITHIN GROUP (',
'           ORDER BY cfg.display_sequence,',
'                    ro.ebs_organization_id',
'       )',
'  FROM ops.adre_inv_item_request_org ro',
'  JOIN ops.adre_inv_item_type_org cfg',
'    ON cfg.item_type_id = :P10_ITEM_TYPE_ID',
'   AND cfg.organization_role = ro.organization_role',
'   AND cfg.ebs_organization_id = ro.ebs_organization_id',
' WHERE ro.item_request_id = :P10_ITEM_REQUEST_ID',
'   AND ro.organization_role = ''TARGET''',
'   AND cfg.active_flag = ''Y''',
'   AND cfg.auto_assign_flag = ''N'''))
,p_source_type=>'QUERY'
,p_display_as=>'NATIVE_SHUTTLE'
,p_named_lov=>'LOV_ADDITIONAL_TARGET_ORGANIZATIONS'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT CASE',
'           WHEN hou.name IS NULL',
'               THEN mp.organization_code',
'           ELSE mp.organization_code || '' - '' || hou.name',
'       END AS display_value,',
'       cfg.ebs_organization_id AS return_value',
'  FROM ops.adre_inv_item_type_org cfg',
'  JOIN apps.mtl_parameters mp',
'    ON mp.organization_id = cfg.ebs_organization_id',
'  LEFT JOIN apps.hr_all_organization_units hou',
'    ON hou.organization_id = cfg.ebs_organization_id',
' WHERE cfg.item_type_id = :P10_ITEM_TYPE_ID',
'   AND cfg.organization_role = ''TARGET''',
'   AND cfg.active_flag = ''Y''',
'   AND cfg.auto_assign_flag = ''N''',
' ORDER BY cfg.display_sequence,',
'          mp.organization_code'))
,p_lov_cascade_parent_items=>'P10_ITEM_TYPE_ID'
,p_ajax_optimize_refresh=>'Y'
,p_cHeight=>1
,p_colspan=>12
