wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(279270961469059001)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Set Request Technical Values'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    -- 2026-09-08 - JCALZADILLA - Set initial request and audit values before automatic form DML.',
'    -- 2026-09-08 - JCALZADILLA - CREATION_DATE is populated by the database default to preserve the full timestamp.',
'    IF :P10_ITEM_REQUEST_ID IS NULL THEN',
'        :P10_REQUEST_STATUS        := ''DRAFT'';',
'        :P10_INITIATOR             := :APP_USER;',
'        :P10_CREATED_BY            := :APP_USER;',
'        :P10_RECORD_VERSION_NUMBER := 1;',
'    ELSE',
'        :P10_RECORD_VERSION_NUMBER :=',
'            NVL(:P10_RECORD_VERSION_NUMBER, 0) + 1;',
'    END IF;',
'',
'    :P10_LAST_UPDATED_BY   := :APP_USER;',
'    :P10_LAST_UPDATE_DATE  := SYSDATE;',
'    :P10_LAST_UPDATE_LOGIN := :APP_SESSION;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>279270961469059001
,p_process_comment=>'2026-09-08 - JCALZADILLA - Sets initial status, initiator and audit values before the automatic form DML process.'
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(267973078216785494)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_region_id=>wwv_flow_imp.id(267952359219785466)
,p_process_type=>'NATIVE_FORM_DML'
,p_process_name=>'Process form Request Workspace'
,p_attribute_01=>'REGION_SOURCE'
,p_attribute_05=>'Y'
,p_attribute_06=>'Y'
,p_attribute_08=>'Y'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
