wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(279271272840059004)
,p_process_sequence=>30
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Initialize Request Organizations'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_master_count NUMBER;',
'    l_changed_by   ops.adre_inv_item_request_org.created_by%TYPE;',
'BEGIN',
'    -- 2026-09-08 - JCALZADILLA - Initialize only automatic organization assignments from OPS configuration.',
'',
'    IF :P10_ITEM_REQUEST_ID IS NULL THEN',
'        RAISE_APPLICATION_ERROR(',
'            -20001,',
'            ''The request header must be saved before organizations are initialized.''',
'        );',
'    END IF;',
'',
'    SELECT COUNT(*)',
'      INTO l_master_count',
'      FROM ops.adre_inv_item_type_org cfg',
'     WHERE cfg.item_type_id = :P10_ITEM_TYPE_ID',
'       AND cfg.organization_role = ''MASTER''',
'       AND cfg.required_flag = ''Y''',
'       AND cfg.auto_assign_flag = ''Y''',
'       AND cfg.active_flag = ''Y'';',
'',
'    IF l_master_count <> 1 THEN',
'        RAISE_APPLICATION_ERROR(',
'            -20002,',
'            ''Exactly one required automatic MASTER Organization must be configured for the selected Item Type.''',
'        );',
'    END IF;',
'',
'    l_changed_by := NVL(:APP_USER, USER);',
'',
'    INSERT INTO ops.adre_inv_item_request_org',
'    (',
'        item_request_id,',
'        organization_role,',
'        assignment_status,',
'        created_by,',
'        creation_date,',
'        last_updated_by,',
'        last_update_date,',
'        last_update_login,',
'        record_version_number,',
'        ebs_organization_id,',
'        ebs_template_id',
'    )',
'    SELECT :P10_ITEM_REQUEST_ID,',
'           cfg.organization_role,',
'           ''DRAFT'',',
'           l_changed_by,',
'           SYSDATE,',
'           l_changed_by,',
'           SYSDATE,',
'           SYS_CONTEXT(''USERENV'', ''SESSIONID''),',
'           1,',
'           cfg.ebs_organization_id,',
'           cfg.ebs_template_id',
'      FROM ops.adre_inv_item_type_org cfg',
'     WHERE cfg.item_type_id = :P10_ITEM_TYPE_ID',
'       AND cfg.auto_assign_flag = ''Y''',
'       AND cfg.active_flag = ''Y''',
'       AND NOT EXISTS',
'           (',
'               SELECT 1',
'                 FROM ops.adre_inv_item_request_org ro',
'                WHERE ro.item_request_id = :P10_ITEM_REQUEST_ID',
'                  AND ro.organization_role = cfg.organization_role',
'                  AND ro.ebs_organization_id = cfg.ebs_organization_id',
'           );',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when=>'DELETE'
,p_process_when_type=>'REQUEST_NOT_EQUAL_CONDITION'
,p_internal_uid=>279271272840059004
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(279382646998638802)
,p_process_sequence=>40
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Initialize Request Attributes'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    INSERT INTO ops.adre_inv_item_attr_value (',
'        request_org_id,',
'        item_attribute_id,',
'        attribute_char_value,',
'        attribute_number_value,',
'        attribute_date_value,',
'        value_uom_code,',
'        value_status,',
'        created_by,',
'        last_updated_by,',
'        last_update_login',
'    )',
'    SELECT src.request_org_id,',
'           src.item_attribute_id,',
'           CASE',
'               WHEN src.attribute_data_type IN (''CHAR'', ''YES_NO'')',
'               THEN src.default_value',
'           END,',
'           CASE',
'               WHEN src.attribute_data_type = ''NUMBER''',
'               THEN TO_NUMBER(src.default_value)',
'           END,',
'           CASE',
'               WHEN src.attribute_data_type = ''DATE''',
'               THEN TO_DATE(src.default_value, ''YYYY-MM-DD'')',
'           END,',
'           src.unit_of_measure,',
'           ''DRAFT'',',
'           :APP_USER,',
'           :APP_USER,',
'           :APP_SESSION',
'      FROM (',
'          SELECT ro.request_org_id,',
'                 ita.item_attribute_id,',
'                 a.attribute_data_type,',
'                 a.unit_of_measure,',
'                 COALESCE(',
'                     ita.default_value,',
'                     a.default_value',
'                 ) AS default_value',
'            FROM ops.adre_inv_item_request_org ro',
'            JOIN ops.adre_inv_item_type_attr ita',
'              ON ita.item_type_id = :P10_ITEM_TYPE_ID',
'             AND ita.organization_scope = ro.organization_role',
'             AND ita.active_flag = ''Y''',
'            JOIN ops.adre_inv_item_attribute a',
'              ON a.item_attribute_id = ita.item_attribute_id',
'             AND a.active_flag = ''Y''',
'           WHERE ro.item_request_id = :P10_ITEM_REQUEST_ID',
'      ) src',
'     WHERE NOT EXISTS (',
'           SELECT 1',
'             FROM ops.adre_inv_item_attr_value av',
'            WHERE av.request_org_id = src.request_org_id',
'              AND av.item_attribute_id = src.item_attribute_id',
'     );',
'',
'    UPDATE ops.adre_inv_item_attr_value av',
'       SET av.value_uom_code = (',
'               SELECT a.unit_of_measure',
'                 FROM ops.adre_inv_item_attribute a',
'                WHERE a.item_attribute_id = av.item_attribute_id',
'           ),',
'           av.last_updated_by = :APP_USER,',
'           av.last_update_date = SYSDATE,',
'           av.last_update_login = :APP_SESSION,',
'           av.record_version_number = av.record_version_number + 1',
'     WHERE av.request_org_id IN (',
'               SELECT ro.request_org_id',
'                 FROM ops.adre_inv_item_request_org ro',
'                WHERE ro.item_request_id = :P10_ITEM_REQUEST_ID',
'           )',
'       AND av.value_uom_code IS NULL',
'       AND EXISTS (',
'               SELECT 1',
'                 FROM ops.adre_inv_item_attribute a',
'                WHERE a.item_attribute_id = av.item_attribute_id',
'                  AND a.unit_of_measure IS NOT NULL',
'           );',
'END;',
''))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when=>'DELETE'
,p_process_when_type=>'REQUEST_NOT_EQUAL_CONDITION'
,p_internal_uid=>279382646998638802
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(267972689466785494)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
