wwv_flow_imp_page.create_page_validation(
 p_id=>wwv_flow_imp.id(279385323937638829)
,p_validation_name=>'Required Attribute Value'
,p_validation_sequence=>10
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_required_flag       VARCHAR2(1);',
'    l_attribute_data_type VARCHAR2(30);',
'BEGIN',
'    SELECT ita.required_flag,',
'           a.attribute_data_type',
'      INTO l_required_flag,',
'           l_attribute_data_type',
'      FROM ops.adre_inv_item_attr_value av',
'      JOIN ops.adre_inv_item_request_org ro',
'        ON ro.request_org_id = av.request_org_id',
'      JOIN ops.adre_inv_item_request r',
'        ON r.item_request_id = ro.item_request_id',
'      JOIN ops.adre_inv_item_attribute a',
'        ON a.item_attribute_id = av.item_attribute_id',
'      JOIN ops.adre_inv_item_type_attr ita',
'        ON ita.item_type_id = r.item_type_id',
'       AND ita.item_attribute_id = av.item_attribute_id',
'       AND ita.organization_scope = ro.organization_role',
'     WHERE av.item_attr_value_id = :P11_ITEM_ATTR_VALUE_ID;',
'',
'    IF l_required_flag = ''N'' THEN',
'        RETURN TRUE;',
'    END IF;',
'',
'    IF l_attribute_data_type = ''CHAR'' THEN',
'        RETURN TRIM(:P11_CHAR_VALUE) IS NOT NULL;',
'    ELSIF l_attribute_data_type = ''YES_NO'' THEN',
'        RETURN :P11_YES_NO_VALUE IS NOT NULL;',
'    ELSIF l_attribute_data_type = ''NUMBER'' THEN',
'        RETURN :P11_NUMBER_VALUE IS NOT NULL;',
'    ELSIF l_attribute_data_type = ''DATE'' THEN',
'        RETURN :P11_DATE_VALUE IS NOT NULL;',
'    END IF;',
'',
'    RETURN FALSE;',
'END;'))
,p_validation2=>'PLSQL'
,p_validation_type=>'FUNC_BODY_RETURNING_BOOLEAN'
,p_error_message=>'Value is required for this attribute.'
,p_when_button_pressed=>wwv_flow_imp.id(279385007417638826)
,p_error_display_location=>'INLINE_WITH_FIELD_AND_NOTIFICATION'
);
