 p_id=>wwv_flow_imp.id(279385416847638830)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Save Attribute Value'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_attribute_data_type VARCHAR2(30);',
'BEGIN',
'    SELECT a.attribute_data_type',
'      INTO l_attribute_data_type',
'      FROM ops.adre_inv_item_attr_value av',
'      JOIN ops.adre_inv_item_attribute a',
'        ON a.item_attribute_id = av.item_attribute_id',
'     WHERE av.item_attr_value_id = :P11_ITEM_ATTR_VALUE_ID;',
'',
'    UPDATE ops.adre_inv_item_attr_value',
'       SET attribute_char_value =',
'               CASE',
'                   WHEN l_attribute_data_type = ''CHAR''',
'                       THEN :P11_CHAR_VALUE',
'                   WHEN l_attribute_data_type = ''YES_NO''',
'                       THEN :P11_YES_NO_VALUE',
'                   ELSE NULL',
'               END,',
'           attribute_number_value =',
'               CASE',
'                   WHEN l_attribute_data_type = ''NUMBER''',
'                       THEN :P11_NUMBER_VALUE',
'                   ELSE NULL',
'               END,',
'           attribute_date_value =',
'               CASE',
'                   WHEN l_attribute_data_type = ''DATE''',
'                       THEN :P11_DATE_VALUE',
'                   ELSE NULL',
'               END,',
'           value_status = ''DRAFT'',',
'           last_updated_by = :APP_USER,',
'           last_update_date = SYSDATE,',
'           last_update_login = :APP_SESSION,',
'           record_version_number = record_version_number + 1',
'     WHERE item_attr_value_id = :P11_ITEM_ATTR_VALUE_ID;',
'',
'    IF SQL%ROWCOUNT = 0 THEN',
'        raise_application_error(',
'            -20001,',
'            ''The attribute value could not be found.''',
'        );',
'    END IF;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(279385007417638826)
,p_internal_uid=>279385416847638830
);
