,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Load Attribute Details'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    SELECT mp.organization_code,',
'           a.attribute_name,',
'           a.attribute_data_type,',
'           CASE',
'               WHEN a.attribute_data_type = ''CHAR''',
'               THEN av.attribute_char_value',
'           END,',
'           CASE',
'               WHEN a.attribute_data_type = ''YES_NO''',
'               THEN av.attribute_char_value',
'           END,',
'           av.attribute_number_value,',
'           av.attribute_date_value,',
'           COALESCE(',
'               av.value_uom_code,',
'               a.unit_of_measure',
'           )',
'      INTO :P11_ORGANIZATION_CODE,',
'           :P11_ATTRIBUTE_NAME,',
'           :P11_ATTRIBUTE_DATA_TYPE,',
'           :P11_CHAR_VALUE,',
'           :P11_YES_NO_VALUE,',
'           :P11_NUMBER_VALUE,',
'           :P11_DATE_VALUE,',
'           :P11_VALUE_UOM_CODE',
'      FROM ops.adre_inv_item_attr_value av',
'      JOIN ops.adre_inv_item_request_org ro',
'        ON ro.request_org_id = av.request_org_id',
'      JOIN apps.mtl_parameters mp',
'        ON mp.organization_id = ro.ebs_organization_id',
'      JOIN ops.adre_inv_item_attribute a',
'        ON a.item_attribute_id = av.item_attribute_id',
'     WHERE av.item_attr_value_id = :P11_ITEM_ATTR_VALUE_ID;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_process_when=>'P11_ITEM_ATTR_VALUE_ID'
,p_process_when_type=>'ITEM_IS_NOT_NULL'
,p_internal_uid=>279384884176638824
);
end;
