wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(280087760001100902)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Save Category'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_request_status ops.adre_inv_item_request.request_status%TYPE;',
'    l_org_role       ops.adre_inv_item_request_org.organization_role%TYPE;',
'    l_category_value ops.adre_inv_item_category.category_value%TYPE;',
'BEGIN',
'    IF :P12_EBS_CATEGORY_ID IS NULL THEN',
'        raise_application_error(-20001, ''Please select a category.'');',
'    END IF;',
'',
'    BEGIN',
'        SELECT r.request_status,',
'               ro.organization_role',
'          INTO l_request_status,',
'               l_org_role',
'          FROM ops.adre_inv_item_request r',
'          JOIN ops.adre_inv_item_request_org ro',
'            ON ro.item_request_id = r.item_request_id',
'         WHERE r.item_request_id = :P10_ITEM_REQUEST_ID',
'           AND ro.request_org_id = :P12_REQUEST_ORG_ID',
'           FOR UPDATE OF r.request_status;',
'    EXCEPTION',
'        WHEN NO_DATA_FOUND THEN',
'            raise_application_error(',
'                -20001,',
'                ''The organization does not belong to the current request.''',
'            );',
'    END;',
'',
'    IF NVL(l_request_status, ''UNKNOWN'') <> ''DRAFT'' THEN',
'        raise_application_error(',
'            -20001,',
'            ''Categories can only be edited while the request is in DRAFT.''',
'        );',
'    END IF;',
'',
'    BEGIN',
'        SELECT c.concatenated_segments',
'          INTO l_category_value',
'          FROM apps.mtl_categories_kfv c',
'          JOIN apps.mtl_category_sets_b cs',
'            ON cs.structure_id = c.structure_id',
'         WHERE c.category_id = :P12_EBS_CATEGORY_ID',
'           AND cs.category_set_id = :P12_EBS_CATEGORY_SET_ID',
'           AND NVL(c.enabled_flag, ''Y'') = ''Y''',
'           AND (c.disable_date IS NULL OR c.disable_date > SYSDATE)',
'           AND (cs.control_level = 2',
'                OR (cs.control_level = 1 AND l_org_role = ''MASTER''))',
'           AND EXISTS (',
'               SELECT 1',
'                 FROM ops.adre_cat_sets cfg',
'                WHERE cfg.category_set_id = cs.category_set_id',
'           );',
'    EXCEPTION',
'        WHEN NO_DATA_FOUND THEN',
'            raise_application_error(',
'                -20001,',
'                ''The selected category is not available for this category set and organization.''',
'            );',
'    END;',
'',
'    MERGE INTO ops.adre_inv_item_category dst',
'    USING (',
'        SELECT :P12_REQUEST_ORG_ID AS request_org_id,',
'               :P12_EBS_CATEGORY_SET_ID AS ebs_category_set_id',
'          FROM dual',
'    ) src',
'       ON (dst.request_org_id = src.request_org_id',
'           AND dst.ebs_category_set_id = src.ebs_category_set_id)',
'    WHEN MATCHED THEN',
'        UPDATE SET',
'            dst.ebs_category_id = :P12_EBS_CATEGORY_ID,',
'            dst.category_value = l_category_value,',
'            dst.last_updated_by = :APP_USER,',
'            dst.last_update_date = SYSDATE,',
'            dst.record_version_number = dst.record_version_number + 1',
'        WHERE dst.assignment_status = ''DRAFT''',
'    WHEN NOT MATCHED THEN',
'        INSERT (',
'            request_org_id,',
'            ebs_category_set_id,',
'            ebs_category_id,',
'            category_value,',
'            assignment_status,',
'            created_by,',
'            creation_date,',
'            last_updated_by,',
'            last_update_date,',
'            record_version_number',
'        )',
'        VALUES (',
'            src.request_org_id,',
'            src.ebs_category_set_id,',
'            :P12_EBS_CATEGORY_ID,',
'            l_category_value,',
'            ''DRAFT'',',
'            :APP_USER,',
'            SYSDATE,',
'            :APP_USER,',
'            SYSDATE,',
'            1',
'        );',
'',
'    IF SQL%ROWCOUNT = 0 THEN',
'        raise_application_error(',
'            -20001,',
'            ''This category assignment is no longer in DRAFT. Reopen the request.''',
'        );',
'    END IF;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(280087613150100901)
,p_process_success_message=>'Category saved.'
,p_internal_uid=>280087760001100902
);
