wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(279387434484638850)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Load Category Details'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    SELECT mp.organization_code,',
'           cfg.category_set_name,',
'           cat.ebs_category_id',
'      INTO :P12_ORGANIZATION_CODE,',
'           :P12_CATEGORY_SET_NAME,',
'           :P12_EBS_CATEGORY_ID',
'      FROM ops.adre_inv_item_request_org ro',
'      JOIN apps.mtl_parameters mp',
'        ON mp.organization_id = ro.ebs_organization_id',
'      JOIN ops.adre_cat_sets cfg',
'        ON cfg.category_set_id = :P12_EBS_CATEGORY_SET_ID',
'      JOIN apps.mtl_category_sets_b cs',
'        ON cs.category_set_id = cfg.category_set_id',
'      LEFT JOIN ops.adre_inv_item_category cat',
'        ON cat.request_org_id = ro.request_org_id',
'       AND cat.ebs_category_set_id = cfg.category_set_id',
'     WHERE ro.request_org_id = :P12_REQUEST_ORG_ID',
'       AND ro.item_request_id = :P10_ITEM_REQUEST_ID',
'       AND (',
'           cs.control_level = 2',
'           OR (',
'               cs.control_level = 1',
'               AND ro.organization_role = ''MASTER''',
'           )',
'       );',
'EXCEPTION',
'    WHEN NO_DATA_FOUND THEN',
'        raise_application_error(',
'            -20001,',
'            ''The organization or category set is not valid for this request.''',
'        );',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>279387434484638850
);
end;
